import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _convolve_max(h):
    return np.max(np.convolve(h, h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    # Seed
    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.maximum(h0, 0.0)
        if h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        x = np.linspace(-1, 1, 200)
        h0 = np.maximum(1.0 - x * x, 0.0) + 1e-3

    best = h0.copy()
    bestC = _C(best)

    # Try multiple resolutions; the true optimum of C1 is likely a smooth
    # shape, so higher resolution helps. Optimize at moderate N then upsample.
    rng = np.random.default_rng(1234)

    def smooth_refine(h, iters, deadline):
        """Multiplicative coordinate descent on heights."""
        h = h.copy()
        N = len(h)
        curC = _C(h)
        order = np.arange(N)
        for it in range(iters):
            if time.process_time() >= deadline:
                break
            rng.shuffle(order)
            improved = False
            for i in order:
                if time.process_time() >= deadline:
                    break
                old = h[i]
                if old <= 0:
                    # try making it nonzero
                    s = h.sum()
                    if s <= 0:
                        continue
                    h[i] = 0.01 * s / N
                    c = _C(h)
                    if c < curC - 1e-12:
                        curC = c
                        improved = True
                    else:
                        h[i] = old
                    continue
                best_mult = 1.0
                best_c = curC
                for mult in (0.6, 0.8, 0.9, 0.95, 1.05, 1.1, 1.25, 1.5):
                    h[i] = old * mult
                    c = _C(h)
                    if c < best_c - 1e-12:
                        best_c = c
                        best_mult = mult
                h[i] = old * best_mult
                if best_mult != 1.0:
                    curC = best_c
                    improved = True
            if not improved:
                break
        return h, curC

    # Try a few sizes; start with start's size, then grow.
    sizes = []
    if start is not None:
        sizes.append(len(best))
    for n in (60, 100, 150, 220, 300, 400, 550, 750):
        if n not in sizes:
            sizes.append(n)

    for N in sizes:
        if time.process_time() >= deadline:
            break
        if N > 30000:
            continue
        # Build initial guess at this N by interpolating best
        if N == len(best):
            h = best.copy()
        else:
            xold = np.linspace(0, 1, len(best))
            xnew = np.linspace(0, 1, N)
            h = np.interp(xnew, xold, best)
            h = np.maximum(h, 0.0)
            if h.sum() <= 0:
                h = np.ones(N)
        h, c = smooth_refine(h, iters=8, deadline=deadline)
        if c < bestC:
            bestC = c
            best = h

    # Final polish with scipy on log-heights to keep positivity, optimizing
    # a smooth surrogate? Instead do more coordinate descent on the best.
    if time.process_time() < deadline:
        best, bestC = smooth_refine(best, iters=50, deadline=deadline)

    # Try upsampling the best and refining once more (finer resolution often
    # reveals a lower C for the same smooth shape).
    if time.process_time() < deadline and len(best) < 2000:
        for N in (len(best) * 2, len(best) * 3):
            if N > 30000 or time.process_time() >= deadline:
                break
            xold = np.linspace(0, 1, len(best))
            xnew = np.linspace(0, 1, N)
            h = np.interp(xnew, xold, best)
            h = np.maximum(h, 0.0)
            h, c = smooth_refine(h, iters=6, deadline=deadline)
            if c < bestC:
                bestC = c
                best = h

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    return best

import numpy as np
import time


def _C_fast(h):
    """Exact C value, normalized so sum(h)=1 for stability."""
    s = h.sum()
    if s <= 0:
        return np.inf
    hh = h / s
    return 2.0 * len(h) * np.max(np.convolve(hh, hh))


def _C_grad(h, eps=1e-7):
    """Return C and gradient of C w.r.t. h (normalized form)."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf, np.zeros_like(h)
    hn = h / s
    conv = np.convolve(hn, hn)
    m = np.max(conv)
    N = len(h)
    C = 2.0 * N * m
    # gradient of max(conv) w.r.t. hn: at argmax index k, d(conv[k])/d(hn[i]) = 2*hn[k-i] (with bounds)
    k = int(np.argmax(conv))
    g_hn = np.zeros(N)
    # conv[k] = sum_i hn[i]*hn[k-i] for 0<=k-i<N
    lo = max(0, k - (N - 1))
    hi = min(N - 1, k)
    # d/d hn[i] = 2*hn[k-i]
    for i in range(lo, hi + 1):
        g_hn[i] = 2.0 * hn[k - i]
    # chain rule through hn = h/s: d(hn[i])/d(h[j]) = (delta_ij - hn[i])/s
    g_h = (g_hn - g_hn.dot(hn)) / s
    return C, 2.0 * N * g_h


def _project_nonneg(h):
    return np.maximum(h, 0.0)


def _smooth_bump(N, kind="cos"):
    x = (np.arange(N) + 0.5) / N * 2 - 1
    if kind == "cos":
        return 0.5 * (1 + np.cos(np.pi * x))
    if kind == "tri":
        return np.maximum(1 - np.abs(x), 0)
    if kind == "par":
        return np.maximum(1 - x * x, 0)
    if kind == "gauss":
        return np.exp(-4 * x * x)
    return np.ones(N)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    rng = np.random.default_rng(20240501)

    # Build candidate pool
    candidates = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            candidates.append(np.maximum(s, 0.0))

    for N in [100, 200, 300, 400, 500, 700, 900, 1200, 1600, 2200, 3000]:
        for kind in ("cos", "par", "tri", "gauss"):
            candidates.append(_smooth_bump(N, kind))

    # Score
    scored = []
    for c in candidates:
        cc = _C_fast(c)
        if np.isfinite(cc):
            scored.append((cc, c))
    scored.sort(key=lambda t: t[0])
    best_c, best_h = scored[0]

    def project_and_score(h):
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            return np.inf, h
        return _C_fast(h), h

    # Gradient-based refinement with adaptive step (projected gradient on log-ish scale)
    def refine(h_init, end_time, max_iters=100000):
        h = np.maximum(np.asarray(h_init, dtype=float).copy(), 1e-12)
        C, _ = project_and_score(h)
        lr = 0.05
        best_h = h.copy()
        best_C = C
        it = 0
        while time.process_time() < end_time and it < max_iters:
            it += 1
            C, g = _C_grad(h)
            # Normalize gradient
            gn = np.linalg.norm(g)
            if gn < 1e-15:
                break
            # Step in negative gradient direction, projected to nonneg
            h_new = h - lr * g / gn * h  # scale by h (multiplicative-ish)
            h_new = np.maximum(h_new, 0.0)
            if h_new.sum() <= 0:
                lr *= 0.5
                continue
            C_new, h_new = project_and_score(h_new)
            if C_new < C - 1e-14:
                h = h_new
                if C_new < best_C - 1e-14:
                    best_C = C_new
                    best_h = h.copy()
                lr *= 1.05
            else:
                lr *= 0.6
            if lr < 1e-6:
                # restart with random perturbation
                h = np.maximum(best_h * (1 + 0.01 * rng.standard_normal(len(best_h))), 0.0)
                if h.sum() <= 0:
                    h = best_h.copy()
                lr = 0.02
        return best_h, best_C

    # Refine top candidates
    for cval, cand in scored[:3]:
        if time.process_time() >= deadline:
            break
        rh, rc = refine(cand, deadline)
        if rc < best_c:
            best_c, best_h = rc, rh

    # Coordinate descent polish on best
    def coord_polish(h, end_time):
        h = h.copy()
        C = _C_fast(h)
        N = len(h)
        idxs = np.arange(N)
        step = 0.3
        while time.process_time() < end_time:
            improved = False
            rng.shuffle(idxs)
            for i in idxs:
                if time.process_time() >= end_time:
                    break
                old = h[i]
                best_mult = 1.0
                bestCl = C
                for mult in (1 - step, 1 - step / 2, 1 + step / 2, 1 + step):
                    h[i] = old * mult
                    c = _C_fast(h)
                    if c < bestCl - 1e-14:
                        bestCl = c
                        best_mult = mult
                h[i] = old * best_mult
                if best_mult != 1.0:
                    C = bestCl
                    improved = True
            if not improved:
                if step < 0.02:
                    break
                step *= 0.6
        return h, C

    if time.process_time() < deadline:
        rh, rc = coord_polish(best_h, deadline)
        if rc < best_c:
            best_c, best_h = rc, rh

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    if best_h.size > 30000:
        best_h = best_h[:30000]
    return best_h

import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h, k=None):
    """Exact C and its gradient wrt h (normalized internally)."""
    s = h.sum()
    if s <= 0:
        return np.inf, np.zeros_like(h)
    hn = h / s
    N = len(h)
    conv = np.convolve(hn, hn)
    m = conv.max()
    if k is None:
        k = int(np.argmax(conv))
    C = 2.0 * N * m
    # d conv[k]/d hn[i] = 2*hn[k-i]
    lo = max(0, k - (N - 1))
    hi = min(N - 1, k)
    g_hn = np.zeros(N)
    g_hn[lo:hi + 1] = 2.0 * hn[k - (lo:hi + 1)]
    # chain through hn = h/s
    g_h = (g_hn - g_hn.dot(hn)) / s
    return C, 2.0 * N * g_h


def _resample(h, N):
    """Linear-interp resample h to length N."""
    n = len(h)
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _refine_grad(h, end_time, lr0=0.3, max_iters=200000):
    """Projected gradient descent with adaptive lr, using exact gradient."""
    h = np.maximum(np.asarray(h, dtype=float), 0.0).copy()
    if h.sum() <= 0:
        return h, np.inf
    C, _ = _C_and_grad(h)
    best_h = h.copy()
    best_C = C
    lr = lr0
    it = 0
    while time.process_time() < end_time and it < max_iters:
        it += 1
        C, g = _C_and_grad(h)
        gn = np.linalg.norm(g) + 1e-30
        # direction scaled by h (multiplicative-like) mixed with additive
        d = g / gn
        h_new = h - lr * d * (h + 0.01 * h.mean())
        h_new = np.maximum(h_new, 0.0)
        if h_new.sum() <= 0:
            lr *= 0.5
            if lr < 1e-9:
                break
            continue
        C_new = _C(h_new)
        if C_new < C - 1e-15:
            h = h_new
            if C_new < best_C - 1e-15:
                best_C = C_new
                best_h = h.copy()
            lr *= 1.1
        else:
            lr *= 0.5
            if lr < 1e-9:
                break
    return best_h, best_C


def _coord_polish(h, end_time):
    """Coordinate multiplicative descent on best."""
    h = h.copy()
    C = _C(h)
    N = len(h)
    rng = np.random.default_rng(1)
    step = 0.2
    while time.process_time() < end_time:
        improved = False
        order = rng.permutation(N)
        for i in order:
            if time.process_time() >= end_time:
                break
            old = h[i]
            best_mult = 1.0
            bestC = C
            for mult in (1 - step, 1 - step * 0.5, 1 + step * 0.5, 1 + step):
                h[i] = old * mult
                c = _C(h)
                if c < bestC - 1e-15:
                    bestC = c
                    best_mult = mult
            h[i] = old * best_mult
            if best_mult != 1.0:
                C = bestC
                improved = True
        if not improved:
            step *= 0.5
            if step < 0.005:
                break
    return h, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0

    rng = np.random.default_rng(987654321)

    # Build candidates
    candidates = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            candidates.append(np.maximum(s, 0.0))

    def smooth(N, kind):
        x = (np.arange(N) + 0.5) / N * 2 - 1
        if kind == "cos":
            return 0.5 * (1 + np.cos(np.pi * x))
        if kind == "par":
            return np.maximum(1 - x * x, 0)
        if kind == "tri":
            return np.maximum(1 - np.abs(x), 0)
        if kind == "gauss":
            return np.exp(-4 * x * x)
        if kind == "cubic":
            return np.maximum((1 - x * x), 0) ** 1.5
        return np.ones(N)

    for N in [80, 120, 160, 200, 260, 340, 450, 600, 800, 1100, 1500, 2000, 2800]:
        for kind in ("cos", "par", "gauss", "cubic"):
            candidates.append(smooth(N, kind))

    scored = []
    for c in candidates:
        cc = _C(c)
        if np.isfinite(cc):
            scored.append((cc, c))
    scored.sort(key=lambda t: t[0])
    best_c, best_h = scored[0]
    best_h = np.maximum(best_h, 0.0)

    # If start given, also try resampling it to various lengths and refining
    refine_seeds = [best_h]
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float).ravel(), 0.0)
        if s.sum() > 0:
            for N in (len(s), 200, 400, 800):
                if N >= 4:
                    refine_seeds.append(_resample(s, N))

    # Phase 1: gradient refinement on best seeds
    phase1_end = t0 + (deadline - t0) * 0.75
    for seed in refine_seeds[:3]:
        if time.process_time() >= phase1_end:
            break
        rh, rc = _refine_grad(seed, phase1_end)
        if rc < best_c:
            best_c, best_h = rc, rh

    # Phase 2: coordinate polish
    if time.process_time() < deadline:
        rh, rc = _coord_polish(best_h, deadline)
        if rc < best_c:
            best_c, best_h = rc, rh

    # Phase 3: try a couple of different length resamplings of best_h and refine
    if time.process_time() < deadline:
        for N in (max(20, len(best_h) // 2), len(best_h) * 2):
            if N > 30000 or N < 4:
                continue
            if time.process_time() >= deadline:
                break
            seed = _resample(best_h, N)
            rh, rc = _refine_grad(seed, deadline, lr0=0.1)
            if rc < best_c:
                best_c, best_h = rc, rh

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    if best_h.size > 30000:
        best_h = best_h[:30000]
    return best_h

import numpy as np
import time
from scipy.signal import fftconvolve


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(fftconvolve(h, h)) / (s * s)


def _conv(h):
    return fftconvolve(h, h)


def _C_grad(h):
    """C and analytic gradient of C w.r.t. h at the argmax knot."""
    N = len(h)
    s = h.sum()
    if s <= 0:
        return np.inf, np.zeros(N)
    conv = _conv(h)
    k = int(np.argmax(conv))
    m = conv[k]
    C = 2.0 * N * m / (s * s)
    g = np.zeros(N)
    lo = max(0, k - (N - 1))
    hi = min(N - 1, k)
    idx = np.arange(lo, hi + 1)
    g[idx] = 2.0 * h[k - idx]
    dC = 2.0 * N / (s * s) * g - 4.0 * N * m / (s * s * s)
    return C, dC


def _refine(h, end_time, rng, lr0=0.03, max_iters=10**9):
    h = np.maximum(np.asarray(h, dtype=float).copy(), 1e-12)
    C, _ = _C_grad(h)
    best_h = h.copy()
    best_C = C
    lr = lr0
    it = 0
    while time.process_time() < end_time and it < max_iters:
        it += 1
        C, g = _C_grad(h)
        gn = np.linalg.norm(g)
        if gn < 1e-18:
            break
        step = lr * g / gn * np.maximum(h, 1e-9)
        h_new = np.maximum(h - step, 0.0)
        if h_new.sum() <= 0:
            lr *= 0.5
            continue
        C_new = _C(h_new)
        if C_new < C - 1e-15:
            h = h_new
            if C_new < best_C - 1e-15:
                best_C = C_new
                best_h = h.copy()
            lr *= 1.05
        else:
            lr *= 0.7
        if lr < 1e-10:
            kick = best_h * (1 + 0.01 * rng.standard_normal(len(best_h)))
            h = np.maximum(kick, 0.0)
            if h.sum() <= 0:
                h = best_h.copy()
            lr = lr0
    return best_h, best_C


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    # piecewise-constant resample preserving mass
    edges_src = np.linspace(0, n, n + 1)
    edges_dst = np.linspace(0, n, N + 1)
    cum = np.concatenate([[0.0], np.cumsum(h)])
    out = np.zeros(N)
    for j in range(N):
        a, b = edges_dst[j], edges_dst[j + 1]
        # integral of h over [a,b] / (b-a)
        def F(x):
            i = int(np.floor(x))
            i = min(i, n - 1)
            return cum[i] + h[i] * (x - i)
        out[j] = (F(b) - F(a)) / (b - a)
    return out


def _coord_polish(h, end_time, rng):
    h = h.copy()
    C = _C(h)
    step = 0.2
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(len(h))
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                break
            old = h[i]
            best_m = 1.0
            bC = C
            for m in (1 - step, 1 - step / 2, 1 + step / 2, 1 + step):
                h[i] = old * m
                c = _C(h)
                if c < bC - 1e-15:
                    bC = c
                    best_m = m
            h[i] = old * best_m
            if best_m != 1.0:
                C = bC
                improved = True
        if not improved:
            if step < 0.005:
                break
            step *= 0.5
    return h, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    rng = np.random.default_rng(1234567)

    pool = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            pool.append(np.maximum(s, 0.0))

    for N in [100, 200, 400, 800, 1500, 3000]:
        x = (np.arange(N) + 0.5) / N * 2 - 1
        pool.append(np.maximum(1 - x * x, 0.0) + 1e-6)
        pool.append(np.maximum(1 - np.abs(x), 0.0) + 1e-6)
        pool.append(0.5 * (1 + np.cos(np.pi * x)) + 1e-6)

    scored = [(_C(c), c) for c in pool if c.sum() > 0]
    scored.sort(key=lambda t: t[0])
    best_C, best_h = scored[0]

    # Refine top candidates.
    n_refine = 3
    remaining = deadline - time.process_time()
    if remaining > 0:
        per = remaining / n_refine
        for cval, cand in scored[:n_refine]:
            now = time.process_time()
            if now >= deadline - 0.5:
                break
            end = min(deadline - 0.5, now + per)
            rh, rc = _refine(cand, end, rng)
            if rc < best_C:
                best_C, best_h = rc, rh

    # Progressive resampling to escape local minima.
    for N_target in [200, 400, 800, 1600, 3000, 1200, 600, 400]:
        if time.process_time() >= deadline - 0.4:
            break
        hu = _resample(best_h, N_target)
        rh, rc = _refine(hu, min(deadline - 0.3, time.process_time() + 1.2), rng)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Final coordinate polish at best resolution.
    if time.process_time() < deadline - 0.2:
        h, C = _coord_polish(best_h, deadline - 0.2, rng)
        if C < best_C:
            best_h, best_C = h, C

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    if best_h.size > 30000:
        best_h = best_h[:30000]
    return best_h

