    dC = 2.0 * N / (s * s) * g - 4.0 * N * m / (s * s * s)
    return C, dC


def _refine(h, end_time, rng, lr0=0.03):
    h = np.maximum(np.asarray(h, dtype=float).copy(), 1e-12)
    C, _ = _C_grad(h)
    best_h = h.copy()
    best_C = C
    lr = lr0
    while time.process_time() < end_time:
        C, g = _C_grad(h)
        gn = np.linalg.norm(g)
        if gn < 1e-18:
            break
        step = lr * g / gn * np.maximum(h, 1e-9)
        h_new = np.maximum(h - step, 0.0)
        if h_new.sum() <= 0:
            lr *= 0.5
            continue
        C_new = _C(h_new)
        if C_new < C - 1e-15:
            h = h_new
            if C_new < best_C - 1e-15:
                best_C = C_new
                best_h = h.copy()
            lr *= 1.05
        else:
            lr *= 0.7
        if lr < 1e-9:
            h = np.maximum(best_h * (1 + 0.008 * rng.standard_normal(len(best_h))), 0.0)
            if h.sum() <= 0:
                h = best_h.copy()
            lr = lr0
    return best_h, best_C


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    x_new = (np.arange(N) + 0.5) / N
    x_old = (np.arange(n) + 0.5) / n
    return np.interp(x_new, x_old, h)


def _fourier_smooth(h, N, sigma):
    hu = _resample(h, N)
    if sigma > 0:
        kx = np.arange(N)
        d = np.minimum(kx, N - kx) / N
        filt = np.exp(-0.5 * (d / sigma) ** 2)
        hf = np.real(np.fft.ifft(np.fft.fft(hu) * filt))
        hu = np.maximum(hf, 0.0)
    return hu


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2
    rng = np.random.default_rng(20240711)

    pool = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            pool.append(np.maximum(s, 0.0))

    for N in [100, 200, 400, 800]:
        x = (np.arange(N) + 0.5) / N * 2 - 1
        pool.append(np.maximum(1 - x * x, 0.0) + 1e-9)
        pool.append(np.maximum(1 - np.abs(x), 0.0) + 1e-9)
        pool.append(0.5 * (1 + np.cos(np.pi * x)) + 1e-9)

    scored = [(_C(c), c) for c in pool if c.sum() > 0]
    scored.sort(key=lambda t: t[0])
    best_C, best_h = scored[0]

    n_refine = 3
    remaining = deadline - time.process_time()
    if remaining > 0:
        per = remaining * 0.35 / n_refine
        for cval, cand in scored[:n_refine]:
            now = time.process_time()
            if now >= deadline:
                break
            end = min(deadline, now + per)
            rh, rc = _refine(cand, end, rng)
            if rc < best_C:
                best_C, best_h = rc, rh

    targets = [200, 400, 600, 800, 1200, 1600, 2400]
    sigmas = [0.008, 0.015, 0.03, 0.05]
    idx = 0
    while time.process_time() < deadline - 0.5 and idx < len(targets) * len(sigmas):
        N_target = targets[idx % len(targets)]
        sigma = sigmas[(idx // len(targets)) % len(sigmas)]
        idx += 1
        hu = _fourier_smooth(best_h, N_target, sigma)
        if hu.sum() <= 0:
            continue
        now = time.process_time()
        end = min(deadline - 0.3, now + 1.0)
        rh, rc = _refine(hu, end, rng)
        if rc < best_C - 1e-12:
            best_C, best_h = rc, rh

    # Coordinate-descent polish with adaptive multiplicative moves.
    h = best_h.copy()
    C = _C(h)
    step = 0.12
    while time.process_time() < deadline:
        improved = False
        order = np.arange(len(h))
        rng.shuffle(order)
        for i in order:
            if time.process_time() >= deadline:
                break
            old = h[i]
            best_m = 1.0
            bC = C
            for m in (1 - step, 1 - step / 2, 1 + step / 2, 1 + step):
                h[i] = old * m
                c = _C(h)
                if c < bC - 1e-14:
                    bC = c
                    best_m = m
            h[i] = old * best_m
            if best_m != 1.0:
                C = bC
                improved = True
        if not improved:
            if step < 0.005:
                break
            step *= 0.5

    if C < best_C:
        best_h, best_C = h, C

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    if best_h.size > 30000:
        best_h = best_h[:30000]
    return best_h

