            kick = best_h * (1 + 0.01 * rng.standard_normal(len(best_h)))
            h = np.maximum(kick, 0.0)
            if h.sum() <= 0:
                h = best_h.copy()
            lr = lr0
    return best_h, best_C


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    cum = np.concatenate([[0.0], np.cumsum(h)])
    edges = np.linspace(0, n, N + 1)

    def F(x):
        i = int(np.floor(x))
        if i >= n:
            return cum[n]
        return cum[i] + h[i] * (x - i)

    out = np.empty(N)
    for j in range(N):
        a, b = edges[j], edges[j + 1]
        out[j] = (F(b) - F(a)) / (b - a)
    return out


def _coord_polish(h, end_time, rng):
    h = np.maximum(h.copy(), 0.0)
