    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(fftconvolve(h, h))) / (s * s)


def _conv_and_C(h):
    s = h.sum()
    conv = fftconvolve(h, h)
    mx = float(np.max(conv))
    return conv, mx, 2.0 * len(h) * mx / (s * s)


def _grad_at(h, kk):
    N = len(h)
    g = np.zeros(N)
    lo = max(0, kk - (N - 1))
    hi = min(N - 1, kk)
    idx = np.arange(lo, hi + 1)
    g[idx] = 2.0 * h[kk - idx]
    return g


def _descent(h, end_time, rng, lr0=0.03):
    """Gradient descent on the single max knot with adaptive lr + plateau escape."""
    h = np.maximum(np.asarray(h, dtype=float).copy(), 1e-12)
    N = len(h)
    h *= N / h.sum()
    conv, mx, C = _conv_and_C(h)
    best_h = h.copy(); best_C = C
    lr = lr0
    stall = 0
    while time.process_time() < end_time:
        conv, mx, C = _conv_and_C(h)
        if C < best_C - 1e-15:
            best_C = C; best_h = h.copy(); stall = 0
        else:
            stall += 1
        k = int(np.argmax(conv))
        g = _grad_at(h, k)
        s = h.sum()
        dC = (2.0 * N / (s * s)) * g - (4.0 * N * mx / (s * s * s))
        dm = dC * np.maximum(h, 1e-9)
        nrm = np.linalg.norm(dm)
        if nrm < 1e-18:
            break
        h = h - lr * dm / nrm * np.maximum(h, 1e-9)
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            h = best_h.copy(); lr *= 0.5; continue
        h *= N / s
        if stall > 60:
            # plateau escape: perturb from best
            h = best_h * np.exp(0.02 * rng.standard_normal(N))
            h = np.maximum(h, 0.0)
            if h.sum() <= 0:
                h = best_h.copy()
            else:
                h *= N / h.sum()
            lr *= 0.85
            stall = 0
    return best_h, best_C


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    x = (np.arange(N) + 0.5) / N * n
    idx = np.clip(x.astype(int), 0, n - 1)
    return np.maximum(h[idx], 0.0)


