            bm = 1.0; bC = C
            for m in (1 - step, 1 - step / 2, 1 + step / 2, 1 + step):
                h[i] = old * m
                c = _C(h)
                if c < bC - 1e-16:
                    bC = c; bm = m
            h[i] = old * bm
            if bm != 1.0:
                C = bC; improved = True
        if not improved:
            if step < 0.001:
                break
            step *= 0.5
    return h, C


def construct(budget_seconds, start):
