import numpy as np
import time
from scipy.signal import fftconvolve


def _conv(h):
    return fftconvolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    cum = np.concatenate([[0.0], np.cumsum(h)])
    edges = np.linspace(0, n, N + 1)
    idx = np.clip(np.floor(edges[:-1]).astype(int), 0, n - 1)
    frac = edges[:-1] - idx
    out = np.empty(N)
    for j in range(N):
        a, b = edges[j], edges[j + 1]
        ia = int(np.floor(a)); ib = int(np.floor(b))
        if ia >= n:
            out[j] = 0.0
        elif ia == ib:
            out[j] = h[min(ia, n - 1)]
        else:
            fa = a - ia; fb = b - ib
            tot = h[ia] * (1.0 - fa) + cum[ib] - cum[min(ia + 1, n)] + h[min(ib, n - 1)] * fb
            out[j] = tot / (b - a)
    return np.maximum(out, 0.0)


def _grad_max(h, conv, kk):
    N = len(h)
    g = np.zeros(N)
    lo = max(0, kk - (N - 1))
    hi = min(N - 1, kk)
    idx = np.arange(lo, hi + 1)
    g[idx] = 2.0 * h[kk - idx]
    return g


def _adam(h0, end_time, rng, lr0=0.01, tol_rel=3e-4, ntop=40):
    h = np.maximum(np.asarray(h0, dtype=float).copy(), 1e-12)
    N = len(h)
    h *= N / h.sum()
    best_h = h.copy()
    best_C = _C(h)
    m = np.zeros(N); v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-12
    lr = lr0; t = 0; stall = 0
    while time.process_time() < end_time:
        t += 1
        s = h.sum()
        conv = _conv(h)
        mx = float(conv.max())
        C = 2.0 * N * mx / (s * s)
        tol = mx * tol_rel
        near = np.where(conv > mx - tol)[0]
        if len(near) == 0:
            near = np.array([int(np.argmax(conv))])
        if len(near) > ntop:
            near = near[np.argsort(-conv[near])[:ntop]]
        g = np.zeros(N)
        for k in near:
            g += _grad_max(h, conv, k)
        g /= len(near)
        dC = (2.0 * N / (s * s)) * g - (4.0 * N * mx / (s * s * s))
        gm = dC * np.maximum(h, 1e-9)
        gn = np.linalg.norm(gm)
        if gn < 1e-18:
            break
        gm /= gn
        m = b1 * m + (1 - b1) * gm
        v = b2 * v + (1 - b2) * gm * gm
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        h_new = h - lr * mhat / (np.sqrt(vhat) + eps) * np.maximum(h, 1e-9)
        h_new = np.maximum(h_new, 0.0)
        s2 = h_new.sum()
        if s2 <= 0:
            h_new = best_h.copy(); lr *= 0.5; continue
        h_new *= N / s2
        h = h_new
        if C < best_C - 1e-16:
            best_C = C; best_h = h.copy(); stall = 0
        else:
            stall += 1
        if stall > 250:
            kick = best_h * (1 + 0.003 * rng.standard_normal(N))
            kick = np.maximum(kick, 0.0)
            if kick.sum() > 0:
                h = kick * (N / kick.sum())
            else:
                h = best_h.copy()
            lr *= 0.85; m[:] = 0; v[:] = 0; t = 1; stall = 0
    c = _C(h)
    if c < best_C:
        best_h = h.copy(); best_C = c
    return best_h, best_C


def _coord_polish(h, end_time, rng, step0=0.05, floor=0.002):
