import numpy as np
import time
from scipy.signal import fftconvolve


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _conv_C(h):
    s = h.sum()
    if s <= 0:
        return None, np.inf, np.inf
    conv = fftconvolve(h, h)
    mx = float(np.max(conv))
    return conv, mx, 2.0 * len(h) * mx / (s * s)


def _subgrad_multi(h, conv, mx, ntop=30, tol=1e-3):
    """Average gradient over knots near the max (robust to symmetric plateaus)."""
    N = len(h)
    s = h.sum()
    thr = mx - tol * mx
    near = np.where(conv >= thr)[0]
    if near.size > ntop:
        near = near[np.argsort(-conv[near])[:ntop]]
    g = np.zeros(N)
    for k in near:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        g[idx] += h[k - idx]
    g /= max(1, near.size)
    dC = (2.0 * N / (s * s)) * g - (4.0 * N * mx / (s * s * s))
    return dC


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    cum = np.concatenate([[0.0], np.cumsum(h)])
    edges = np.linspace(0, n, N + 1)
    out = np.empty(N)
    for j in range(N):
        a, b = edges[j], edges[j + 1]
        ia = int(np.floor(a)); fa = a - ia
        ib = int(np.floor(b)); fb = b - ib
        if ia >= n:
            out[j] = 0.0
        elif ia == ib:
            out[j] = h[ia]
        else:
            tot = h[ia] * (1.0 - fa) + cum[ib] - cum[ia + 1] + h[min(ib, n - 1)] * fb
            out[j] = tot / (b - a)
    return np.maximum(out, 0.0)


def _lbfgs(h, end_time, maxiter=400):
    from scipy.optimize import minimize
    N = len(h)
    h0 = np.maximum(np.asarray(h, dtype=float), 1e-12)
    h0 = h0 * (N / h0.sum())

    def fun(x):
        if time.process_time() >= end_time:
            raise StopIteration
        conv, mx, C = _conv_C(x)
        if not np.isfinite(C):
            return 1e30, np.zeros(N)
        g = _subgrad_multi(x, conv, mx, ntop=20, tol=5e-3)
        return C, g

    try:
        res = minimize(fun, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * N,
                       options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-14})
        x = np.maximum(res.x, 0.0)
        if x.sum() > 0:
            return x, _C(x)
    except (StopIteration, Exception):
        pass
    return h0, _C(h0)


def _adam(h, end_time, rng, lr0=0.02):
    h = np.maximum(np.asarray(h, dtype=float).copy(), 1e-12)
    h *= len(h) / h.sum()
    conv, mx, C = _conv_C(h)
    best_h = h.copy(); best_C = C
    m = np.zeros_like(h); v = np.zeros_like(h)
    b1, b2, eps = 0.9, 0.999, 1e-12
    lr = lr0; t = 0; stall = 0
    while time.process_time() < end_time:
        t += 1
        conv, mx, C = _conv_C(h)
        if C < best_C - 1e-15:
            best_C = C; best_h = h.copy(); stall = 0
        else:
            stall += 1
        g = _subgrad_multi(h, conv, mx, ntop=25, tol=1e-3)
        gm = g * np.maximum(h, 1e-9)
        gn = np.linalg.norm(gm)
        if gn < 1e-18:
            break
        gm /= gn
        m = b1 * m + (1 - b1) * gm
        v = b2 * v + (1 - b2) * gm * gm
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        h = h - lr * mhat / (np.sqrt(vhat) + eps) * np.maximum(h, 1e-9)
        h = np.maximum(h, 0.0)
        s = h.sum()
        if s <= 0:
            h = best_h.copy(); lr *= 0.5; continue
        h *= len(h) / s
        if stall > 400:
            h = np.maximum(best_h * np.exp(0.005 * rng.standard_normal(len(best_h))), 0.0)
            if h.sum() <= 0:
                h = best_h.copy()
            else:
                h *= len(h) / h.sum()
            lr *= 0.9; m[:] = 0; v[:] = 0; t = 1; stall = 0
    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2
    rng = np.random.default_rng(20240607)

    best_h = None; best_C = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            s = np.maximum(s, 0.0)
            best_h = s.copy(); best_C = _C(s)

    if best_h is None:
        N = 800
        x = (np.arange(N) + 0.5) / N * 2 - 1
        best_h = np.maximum(1 - x * x, 0.0) + 1e-6
        best_C = _C(best_h)

    # Phase 1: L-BFGS at current resolution
    if time.process_time() < deadline - 0.5:
        end = min(deadline - 0.3, time.process_time() + 2.5)
        rh, rc = _lbfgs(best_h, end, maxiter=400)
        if rc < best_C - 1e-14:
            best_C, best_h = rc, rh

    # Phase 2: progressive upsampling with L-BFGS + Adam
    for N_target in [1600, 2400, 3200, 4000, 5000, 6000]:
        if time.process_time() >= deadline - 0.5:
            break
        hu = _resample(best_h, N_target)
        if hu.sum() <= 0:
            continue
        end = min(deadline - 0.3, time.process_time() + 1.5)
        rh, rc = _lbfgs(hu, end, maxiter=200)
        if rc < best_C - 1e-14:
            best_C, best_h = rc, rh
        if time.process_time() < deadline - 0.3:
            end = min(deadline - 0.2, time.process_time() + 1.0)
            rh, rc = _adam(best_h, end, rng, lr0=0.015)
            if rc < best_C - 1e-14:
                best_C, best_h = rc, rh

    # Phase 3: final L-BFGS + Adam tail
    if time.process_time() < deadline - 0.3:
        end = min(deadline - 0.15, time.process_time() + (deadline - time.process_time()) * 0.6)
        rh, rc = _lbfgs(best_h, end, maxiter=600)
        if rc < best_C - 1e-14:
            best_C, best_h = rc, rh
    if time.process_time() < deadline - 0.1:
        rh, rc = _adam(best_h, deadline - 0.1, rng, lr0=0.008)
        if rc < best_C - 1e-14:
            best_C, best_h = rc, rh

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    if best_h.size > 30000:
        best_h = best_h[:30000]
    return best_h

