import numpy as np
import time
from scipy.signal import fftconvolve


def _conv(h):
    return fftconvolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    cum = np.concatenate([[0.0], np.cumsum(h)])
    edges = np.linspace(0, n, N + 1)
    idx = np.clip(np.floor(edges[:-1]).astype(int), 0, n - 1)
    frac = edges[:-1] - idx
    nxt = np.clip(idx + 1, 0, n - 1)
    # integral from 0 to x for x in edges
    def integ_at(x):
        i = np.clip(np.floor(x).astype(int), 0, n - 1)
        return cum[i] + h[i] * (x - i)
    out = (integ_at(edges[1:]) - integ_at(edges[:-1])) / (edges[1:] - edges[:-1])
    return np.maximum(out, 0.0)


def _grad_max(h, kk):
    N = len(h)
    g = np.zeros(N)
    lo = max(0, kk - (N - 1))
    hi = min(N - 1, kk)
    idx = np.arange(lo, hi + 1)
    g[idx] = 2.0 * h[kk - idx]
    return g


def _adam(h0, end_time, rng, lr0=0.01, tol_rel=3e-4, ntop=40):
    h = np.maximum(np.asarray(h0, dtype=float).copy(), 1e-12)
    N = len(h)
    h *= N / h.sum()
    best_h = h.copy()
    best_C = _C(h)
    m = np.zeros(N); v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-12
    lr = lr0; t = 0; stall = 0
    while time.process_time() < end_time:
        t += 1
        s = h.sum()
        conv = _conv(h)
        mx = float(conv.max())
        C = 2.0 * N * mx / (s * s)
        tol = mx * tol_rel
        near = np.where(conv > mx - tol)[0]
        if len(near) == 0:
            near = np.array([int(np.argmax(conv))])
        if len(near) > ntop:
            near = near[np.argsort(-conv[near])[:ntop]]
        g = np.zeros(N)
        for k in near:
            g += _grad_max(h, k)
        g /= len(near)
        dC = (2.0 * N / (s * s)) * g - (4.0 * N * mx / (s * s * s))
        gm = dC * np.maximum(h, 1e-9)
        gn = np.linalg.norm(gm)
        if gn < 1e-18:
            break
        gm /= gn
        m = b1 * m + (1 - b1) * gm
        v = b2 * v + (1 - b2) * gm * gm
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        h_new = h - lr * mhat / (np.sqrt(vhat) + eps) * np.maximum(h, 1e-9)
        h_new = np.maximum(h_new, 0.0)
        s2 = h_new.sum()
        if s2 <= 0:
            h_new = best_h.copy(); lr *= 0.5; continue
        h_new *= N / s2
        h = h_new
        if C < best_C - 1e-16:
            best_C = C; best_h = h.copy(); stall = 0
        else:
            stall += 1
        if stall > 250:
            kick = best_h * (1 + 0.003 * rng.standard_normal(N))
            kick = np.maximum(kick, 0.0)
            if kick.sum() > 0:
                h = kick * (N / kick.sum())
            else:
                h = best_h.copy()
            lr *= 0.85; m[:] = 0; v[:] = 0; t = 1; stall = 0
    c = _C(h)
    if c < best_C:
        best_h = h.copy(); best_C = c
    return best_h, best_C


def _coord_polish(h, end_time, rng, step0=0.05, floor=0.002):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    step = step0
    n = len(h)
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                break
            old = h[i]; bC = C; bm = 1.0
            for mlt in (1 - step, 1 - step / 2, 1 + step / 2, 1 + step):
                h[i] = old * mlt
                c = _C(h)
                if c < bC - 1e-15:
                    bC = c; bm = mlt
            h[i] = old * bm
            if bm != 1.0:
                C = bC; improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def _pair_polish(h, end_time, rng, step0=0.02, floor=0.001):
    """Coordinate polish that also perturbs pairs of neighbouring steps."""
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    step = step0
    n = len(h)
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                break
            # single
            old = h[i]; bC = C; bm = 1.0
            for mlt in (1 - step, 1 + step):
                h[i] = old * mlt
                c = _C(h)
                if c < bC - 1e-15:
                    bC = c; bm = mlt
            h[i] = old * bm
            if bm != 1.0:
                C = bC; improved = True
            # pair with neighbour
            if i + 1 < n and time.process_time() < end_time:
                o1 = h[i]; o2 = h[i + 1]
                best = (bC, 1.0, 1.0)
                for m1 in (1 - step, 1 + step):
                    for m2 in (1 - step, 1 + step):
                        h[i] = o1 * m1; h[i + 1] = o2 * m2
                        c = _C(h)
                        if c < best[0] - 1e-15:
                            best = (c, m1, m2)
                h[i] = o1 * best[1]; h[i + 1] = o2 * best[2]
                if best[0] < C - 1e-15:
                    C = best[0]; improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    rng = np.random.default_rng(13571357)

    pool = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            pool.append(np.maximum(s, 0.0))
    for N in [200, 400]:
        x = (np.arange(N) + 0.5) / N * 2 - 1
        pool.append(np.maximum(1 - x * x, 0.0) + 1e-6)
        pool.append(0.5 * (1 + np.cos(np.pi * x)) + 1e-6)

    scored = [(_C(c), c) for c in pool if c.sum() > 0]
    scored.sort(key=lambda t: t[0])
    best_C, best_h = scored[0]

    # Phase 1: refine start with Adam at its own resolution.
    if time.process_time() < deadline - 0.5:
        end = min(deadline - 0.5, time.process_time() + (deadline - time.process_time()) * 0.3)
        rh, rc = _adam(best_h, end, rng, lr0=0.008, tol_rel=3e-4)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Phase 2: upsample ladder, keeping best across levels.
    for N_target in [1200, 1600, 2000, 2400, 2800, 3200, 3600, 4000, 4500, 5000]:
        if time.process_time() >= deadline - 0.4:
            break
        hu = _resample(best_h, N_target)
