        x = (np.arange(N) + 0.5) / N * 2 - 1
        pool.append(np.maximum(1 - x * x, 0.0) + 1e-6)
        pool.append(0.5 * (1 + np.cos(np.pi * x)) + 1e-6)

    scored = [(_C(c), c) for c in pool if c.sum() > 0]
    scored.sort(key=lambda t: t[0])
    best_C, best_h = scored[0]

    # Phase 1: Adam on start (biggest lever).
    if rem() > 0.6:
        end = time.process_time() + rem() * 0.35
        rh, rc = _adam(best_h, end, rng, lr0=0.008, tol_rel=2e-4, topk=60)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Phase 2: upsample ladder, tight Adam at each N.
    ladder = [1200, 1600, 2000, 2400, 2800, 3200, 3600, 4000, 4600, 5200]
    for j, N_target in enumerate(ladder):
        if rem() < 0.5:
