        hu = _resample(best_h, N_target)
        if hu.sum() <= 0:
            continue
        tol = 4e-4 if j < 3 else 2e-4
        end = time.process_time() + min(1.3, rem() * 0.6)
        rh, rc = _adam(hu, end, rng, lr0=0.01, tol_rel=tol, topk=60)
        if rc < best_C - 1e-13:
