import numpy as np
import time
from scipy.signal import fftconvolve


def _conv(h):
    return fftconvolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    cum = np.concatenate([[0.0], np.cumsum(h)])
    edges = np.linspace(0, n, N + 1)

    def integ(x):
        i = np.clip(np.floor(x).astype(int), 0, n - 1)
        return cum[i] + h[i] * (x - i)

    out = (integ(edges[1:]) - integ(edges[:-1])) / (edges[1:] - edges[:-1])
    return np.maximum(out, 0.0)


def _peak_refine(h, end_time, rng, iters_per=1):
    """Subgradient descent on the single winning peak knot with line search."""
    h = np.maximum(h.copy(), 0.0)
    N = len(h)
    best_h = h.copy()
    best_C = _C(h)
    lr = 0.02
    stall = 0
    while time.process_time() < end_time:
        s = h.sum()
        conv = _conv(h)
        mx = float(conv.max())
        C = 2.0 * N * mx / (s * s)
        if C < best_C - 1e-16:
            best_C = C
            best_h = h.copy()
            stall = 0
        else:
            stall += 1
        pk = int(np.argmax(conv))
        lo = max(0, pk - (N - 1))
        hi = min(N - 1, pk)
        idx = np.arange(lo, hi + 1)
        g = np.zeros(N)
        g[idx] = 2.0 * h[pk - idx]
        dC = (2.0 * N / (s * s)) * g - (4.0 * N * mx / (s * s * s))
        dC = dC - dC.mean()
        nrm = np.linalg.norm(dC)
        if nrm < 1e-18:
            break
        dC /= nrm
        h = np.maximum(h - lr * dC, 0.0)
        s2 = h.sum()
        if s2 <= 0:
            h = best_h.copy()
            lr *= 0.5
            continue
        h *= N / s2
        if stall > 60:
            lr *= 0.7
            stall = 0
            if lr < 1e-9:
                break
    c = _C(h)
    if c < best_C:
        best_h, best_C = h, c
    return best_h, best_C


def _fine_coord(h, end_time, rng, step0=0.008, floor=2e-4):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    step = step0
    n = len(h)
    while time.process_time() < end_time:
        improved = False
        mults = (1 - step, 1 - step * 0.5, 1 - step * 0.25,
                 1 + step * 0.25, 1 + step * 0.5, 1 + step)
        idxs = np.arange(n)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            old = h[i]
            bC = C
            bm = 1.0
            for mm in mults:
                h[i] = old * mm
                c = _C(h)
                if c < bC - 1e-16:
                    bC = c
                    bm = mm
            h[i] = old * bm
            if bm != 1.0:
                C = bC
                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.8
    rng = np.random.default_rng(987654321)

