    cum = np.concatenate([[0.0], np.cumsum(h)])
    edges = np.linspace(0, n, N + 1)
    i = np.clip(np.floor(edges).astype(int), 0, n - 1)
    integ = cum[i] + h[i] * (edges - i)
    out = (integ[1:] - integ[:-1]) / (edges[1:] - edges[:-1])
    return np.maximum(out, 0.0)


def _active(conv, mx, tol_rel, topk):
    tol = mx * tol_rel
    near = np.where(conv > mx - tol)[0]
    if len(near) == 0:
        return np.array([int(np.argmax(conv))]), np.array([1.0])
    if len(near) > topk:
        near = near[np.argsort(-conv[near])[:topk]]
    w = conv[near] - (mx - tol)
    w = np.maximum(w, 1e-12)
    w = w / w.sum()
    return near, w


def _grad(h, conv, near, w, N):
    g = np.zeros(N)
    msum = 0.0
    for k, wk in zip(near, w):
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        g[idx] += wk * 2.0 * h[k - idx]
        msum += wk * conv[k]
    return g, msum


def _adam(h0, end_time, rng, lr0=0.01, tol_rel=1e-3, topk=80,
          stall_limit=400, lr_decay=True):
