            lr *= 0.5
            continue
        h_new *= N / s2
        h = h_new
        if C < best_C - 1e-16:
            best_C = C
            best_h = h.copy()
            stall = 0
        else:
            stall += 1
        if stall > stall_limit:
            kick = best_h * (1 + 0.003 * rng.standard_normal(N))
            kick = np.maximum(kick, 0.0)
            if kick.sum() > 0:
                h = kick * (N / kick.sum())
            else:
                h = best_h.copy()
            if lr_decay:
                lr *= 0.85
            m[:] = 0
            v[:] = 0
            t = 1
            stall = 0
    c = _C(h)
    if c < best_C:
        best_h = h.copy()
        best_C = c
    return best_h, best_C


