        t += 1
        s = h.sum()
        conv = _conv(h)
        mx = float(conv.max())
        C = 2.0 * N * mx / (s * s)
        near = _near_set(conv, mx, tol_rel, topk)
        g, mavg = _grad(h, conv, near, N)
        dC = (2.0 * N / (s * s)) * g - (4.0 * N * mavg / (s * s * s))
        gm = dC * np.maximum(h, 1e-9)
        gn = np.linalg.norm(gm)
        if gn < 1e-18:
            break
        gm /= gn
        m = b1 * m + (1 - b1) * gm
        v = b2 * v + (1 - b2) * gm * gm
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        h_new = h - lr * mhat / (np.sqrt(vhat) + eps) * np.maximum(h, 1e-9)
        h_new = np.maximum(h_new, 0.0)
        s2 = h_new.sum()
        if s2 <= 0:
            h_new = best_h.copy()
            lr *= 0.5
            continue
        h_new *= N / s2
        h = h_new
        if C < best_C - 1e-16:
            best_C = C
            best_h = h.copy()
            stall = 0
        else:
            stall += 1
        if stall > stall_max:
            kick = best_h * (1 + kick_amp * rng.standard_normal(N))
            kick = np.maximum(kick, 0.0)
            if kick.sum() > 0:
                h = kick * (N / kick.sum())
