                C = bC
                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
            mults = (1 - step, 1 - step * 0.5, 1 - step * 0.25,
                     1 + step * 0.25, 1 + step * 0.5, 1 + step)
    return h, C


def _smooth(h, sigma):
    r = int(3 * sigma)
    if r < 1:
        return h.copy()
    x = np.arange(-r, r + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    pad = np.concatenate([np.full(r, h[0]), h, np.full(r, h[-1])])
    return np.convolve(pad, k, mode="valid")


def _local_quad(h, i, C, hsum):
    """Try a few multiplier perturbations at index i, return best multiplier."""
    old = h[i]
    best = 1.0
    bestC = C
    for mm in (0.85, 0.92, 0.96, 0.98, 1.0, 1.02, 1.04, 1.08, 1.15):
        if mm == 1.0:
            continue
        h[i] = old * mm
        c = _C(h)
        if c < bestC - 1e-17:
            bestC = c
            best = mm
    h[i] = old * best
    return bestC, best != 1.0


def _pair_coord(h, end_time, rng, step0=0.01, floor=2e-4, span=4):
    """Coordinate descent on pairs of nearby indices (smoother moves)."""
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            j = (i + 1 + rng.integers(0, span)) % n
            oi, oj = h[i], h[j]
            bC = C
            bi, bj = 1.0, 1.0
            for di in (1 - step, 1.0, 1 + step):
                for dj in (1 - step, 1.0, 1 + step):
                    if di == 1.0 and dj == 1.0:
