                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
            mults = (1 - step, 1 - step * 0.5, 1 - step * 0.25,
                     1 + step * 0.25, 1 + step * 0.5, 1 + step)
    return h, C


def _smooth(h, sigma):
    r = int(3 * sigma)
    if r < 1:
        return h.copy()
    x = np.arange(-r, r + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    pad = np.concatenate([np.full(r, h[0]), h, np.full(r, h[-1])])
