    b1, b2, eps = 0.9, 0.999, 1e-12
    lr = lr0
    t = 0
    stall = 0
    while time.process_time() < end_time:
        t += 1
        s = h.sum()
        conv = _conv(h)
        mx = float(conv.max())
        C = 2.0 * N * mx / (s * s)
        tol = mx * tol_rel
        near = np.where(conv > mx - tol)[0]
        if len(near) == 0:
            near = np.array([int(np.argmax(conv))])
        if len(near) > topk:
            near = near[np.argsort(-conv[near])[:topk]]
        g = np.zeros(N)
        msum = 0.0
        for k in near:
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            idx = np.arange(lo, hi + 1)
            g[idx] += 2.0 * h[k - idx]
            msum += conv[k]
        nl = len(near)
        g /= nl
        mavg = msum / nl
        dC = (2.0 * N / (s * s)) * g - (4.0 * N * mavg / (s * s * s))
        gm = dC * np.maximum(h, 1e-9)
        gn = np.linalg.norm(gm)
        if gn < 1e-18:
            break
        gm /= gn
        m = b1 * m + (1 - b1) * gm
        v = b2 * v + (1 - b2) * gm * gm
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        h_new = h - lr * mhat / (np.sqrt(vhat) + eps) * np.maximum(h, 1e-9)
        h_new = np.maximum(h_new, 0.0)
        s2 = h_new.sum()
        if s2 <= 0:
            h_new = best_h.copy()
            lr *= 0.5
            continue
        h_new *= N / s2
        h = h_new
        if C < best_C - 1e-16:
            best_C = C
            best_h = h.copy()
            stall = 0
        else:
            stall += 1
        if stall > stall_limit:
            kick = best_h * (1 + kick_amp * rng.standard_normal(N))
            kick = np.maximum(kick, 0.0)
            if kick.sum() > 0:
                h = kick * (N / kick.sum())
            else:
                h = best_h.copy()
            lr *= 0.85
            m[:] = 0
            v[:] = 0
            t = 1
            stall = 0
    c = _C(h)
    if c < best_C:
        best_h = h.copy()
        best_C = c
    return best_h, best_C


def _pair_coord(h, end_time, rng, step0=0.003, floor=2e-5):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    step = step0
    n = len(h)
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n - 1)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            a0, b0 = h[i], h[i + 1]
            tot = a0 + b0
            if tot <= 0:
                continue
            bC = C
            bfrac = a0 / tot
            for df in (step, step * 0.5, step * 0.25,
                       -step * 0.25, -step * 0.5, -step):
                frac = bfrac + df
                if frac < 0:
                    frac = 0.0
                elif frac > 1:
                    frac = 1.0
                h[i] = tot * frac
                h[i + 1] = tot * (1 - frac)
                c = _C(h)
                if c < bC - 1e-16:
                    bC = c
                    bfrac = frac
            h[i] = tot * bfrac
            h[i + 1] = tot * (1 - bfrac)
            if bC < C - 1e-16:
                C = bC
                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def _single_coord(h, end_time, rng, step0=0.002, floor=1e-6):
    """Single-coordinate multiplicative polish — cheap and effective late."""
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            o = h[i]
            if o <= 0:
                continue
            bC = C
            bm = 1.0
            for m in (1 + step, 1 - step, 1 + step * 0.5, 1 - step * 0.5):
                h[i] = o * m
                c = _C(h)
                if c < bC - 1e-17:
                    bC = c
                    bm = m
            h[i] = o * bm
            if bm != 1.0:
                C = bC
                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.7
    rng = np.random.default_rng(424242)

    def remaining():
        return deadline - time.process_time()

    pool = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            pool.append(np.maximum(s.copy(), 0.0))
    for N in [200, 400]:
        x = (np.arange(N) + 0.5) / N * 2 - 1
        pool.append(np.maximum(1 - x * x, 0.0) + 1e-6)

    scored = [(_C(c), c) for c in pool if c.sum() > 0]
    scored.sort(key=lambda t: t[0])
    best_C, best_h = scored[0]

    if start is not None:
        sym = _mirror(np.maximum(np.asarray(start, float).ravel(), 0.0))
        if sym.sum() > 0:
            cs = _C(sym)
            if cs < best_C:
                best_C, best_h = cs, sym

    if remaining() > 0.5:
        end = time.process_time() + remaining() * 0.06
        rh, rc = _adam(best_h, end, rng, lr0=0.008, tol_rel=3e-4,
                       topk=80, kick_amp=0.002)
        if rc < best_C:
            best_C, best_h = rc, rh

    for N_target in [1600, 2400, 3200, 4000]:
        if remaining() < 0.5:
            break
        hu = _resample(best_h, N_target)
        hu = _mirror(hu)
        if hu.sum() <= 0:
            continue
        end = min(deadline - 0.3, time.process_time() + 0.45)
        rh, rc = _adam(hu, end, rng, lr0=0.01, tol_rel=5e-4, topk=80)
        if rc < best_C - 1e-13:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = time.process_time() + remaining() * 0.10
        rh, rc = _adam(best_h, end, rng, lr0=0.002, tol_rel=2e-4, topk=100,
                       kick_amp=0.0015, stall_limit=500)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = min(deadline - 0.1, time.process_time() + remaining() * 0.20)
        rh, rc = _pair_coord(best_h, end, rng, step0=0.002, floor=2e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Upsample to 5200 then single-coordinate polish: high-resolution
    # coordinate descent converges to a finer optimum than pair-coord at 3200.
    if remaining() > 0.4:
        hu = _resample(best_h, 5200)
        hu = _mirror(hu)
        if hu.sum() > 0:
            end = min(deadline - 0.2, time.process_time() + 0.6)
            rh, rc = _adam(hu, end, rng, lr0=0.004, tol_rel=2e-4, topk=100,
                           kick_amp=0.001, stall_limit=500)
            if rc < best_C:
                best_C, best_h = rc, rh
            else:
                best_h = hu if _C(hu) < best_C else best_h

    if remaining() > 0.3:
        end = min(deadline - 0.05, time.process_time() + remaining() * 0.6)
        rh, rc = _single_coord(best_h, end, rng, step0=0.002, floor=1e-6)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.2:
        end = deadline - 0.03
        rh, rc = _adam(best_h, end, rng, lr0=0.0006, tol_rel=1.2e-4,
                       topk=120, kick_amp=0.0006, stall_limit=600)
        if rc < best_C:
            best_C, best_h = rc, rh

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    if best_h.size > 30000:
        best_h = best_h[:30000]
    return best_h

import numpy as np
import time
from scipy.signal import fftconvolve


def _conv(h):
    return fftconvolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    cum = np.concatenate([[0.0], np.cumsum(h)])
    edges = np.linspace(0, n, N + 1)
    i = np.clip(np.floor(edges).astype(int), 0, n - 1)
    integ = cum[i] + h[i] * (edges - i)
    out = (integ[1:] - integ[:-1]) / (edges[1:] - edges[:-1])
    return np.maximum(out, 0.0)


def _near_set(conv, mx, tol_rel, topk):
    tol = mx * tol_rel
    near = np.where(conv > mx - tol)[0]
    if len(near) == 0:
        return np.array([int(np.argmax(conv))])
    if len(near) > topk:
        near = near[np.argsort(-conv[near])[:topk]]
    return near


def _adam(h0, end_time, rng, lr0=0.01, tol_rel=1e-3, topk=60,
          kick_amp=0.003, stall_max=300):
    h = np.maximum(np.asarray(h0, dtype=float).copy(), 1e-12)
    N = len(h)
    h *= N / h.sum()
    best_h = h.copy()
    best_C = _C(h)
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-12
    lr = lr0
    t = 0
    stall = 0
    while time.process_time() < end_time:
        t += 1
        s = h.sum()
        conv = _conv(h)
        mx = float(conv.max())
        C = 2.0 * N * mx / (s * s)
        near = _near_set(conv, mx, tol_rel, topk)
        g = np.zeros(N)
        msum = 0.0
        for k in near:
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            idx = np.arange(lo, hi + 1)
            g[idx] += 2.0 * h[k - idx]
            msum += conv[k]
        nl = len(near)
        g /= nl
        mavg = msum / nl
        dC = (2.0 * N / (s * s)) * g - (4.0 * N * mavg / (s * s * s))
        gm = dC * np.maximum(h, 1e-9)
        gn = np.linalg.norm(gm)
        if gn < 1e-18:
            break
        gm /= gn
        m = b1 * m + (1 - b1) * gm
        v = b2 * v + (1 - b2) * gm * gm
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        h_new = h - lr * mhat / (np.sqrt(vhat) + eps) * np.maximum(h, 1e-9)
        h_new = np.maximum(h_new, 0.0)
        s2 = h_new.sum()
        if s2 <= 0:
            h_new = best_h.copy()
            lr *= 0.5
            continue
        h_new *= N / s2
        h = h_new
        if C < best_C - 1e-16:
            best_C = C
            best_h = h.copy()
            stall = 0
        else:
            stall += 1
        if stall > stall_max:
            kick = best_h * (1 + kick_amp * rng.standard_normal(N))
            kick = np.maximum(kick, 0.0)
            if kick.sum() > 0:
                h = kick * (N / kick.sum())
            else:
                h = best_h.copy()
            lr *= 0.85
            m[:] = 0
            v[:] = 0
            t = 1
            stall = 0
    c = _C(h)
    if c < best_C:
        best_h = h.copy()
        best_C = c
    return best_h, best_C


def _pair_coord(h, end_time, rng, step0=0.01, floor=2e-4):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0

    def mks(step):
        return [(1 - step, 1 + step), (1 + step, 1 - step),
                (1 - step * 0.5, 1 + step * 0.5), (1 + step * 0.5, 1 - step * 0.5),
                (1 - step * 0.25, 1 + step * 0.25), (1 + step * 0.25, 1 - step * 0.25)]

    mults = mks(step)
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n - 1)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            o1, o2 = h[i], h[i + 1]
            bC = C
            bm1, bm2 = 1.0, 1.0
            for m1, m2 in mults:
                h[i] = o1 * m1
                h[i + 1] = o2 * m2
                c = _C(h)
                if c < bC - 1e-17:
                    bC = c
                    bm1, bm2 = m1, m2
            h[i] = o1 * bm1
            h[i + 1] = o2 * bm2
            if bm1 != 1.0 or bm2 != 1.0:
                C = bC
                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
            mults = mks(step)
    return h, C


def _three_coord(h, end_time, rng, step0=0.006, floor=2e-4):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0

    def pats(step):
        return [(1 - step, 1 + step, 1 - step), (1 + step, 1 - step, 1 + step),
                (1 - step, 1 - step, 1 + step), (1 + step, 1 - step, 1 - step),
                (1 - step * 0.5, 1 + step * 0.5, 1), (1, 1 + step * 0.5, 1 - step * 0.5),
                (1 + step * 0.5, 1, 1 - step * 0.5), (1 - step * 0.5, 1, 1 + step * 0.5)]

    P = pats(step)
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n - 2)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            o = (h[i], h[i + 1], h[i + 2])
            bC = C
            bm = (1.0, 1.0, 1.0)
            for m1, m2, m3 in P:
                h[i] = o[0] * m1
                h[i + 1] = o[1] * m2
                h[i + 2] = o[2] * m3
                c = _C(h)
                if c < bC - 1e-17:
                    bC = c
                    bm = (m1, m2, m3)
            h[i] = o[0] * bm[0]
            h[i + 1] = o[1] * bm[1]
            h[i + 2] = o[2] * bm[2]
            if bm != (1.0, 1.0, 1.0):
                C = bC
                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
            P = pats(step)
    return h, C


