            a0, b0 = h[i], h[i + 1]
            tot = a0 + b0
            if tot <= 0:
                continue
            bC = C
            bfrac = a0 / tot
            for df in (step, step * 0.5, step * 0.25,
                       -step * 0.25, -step * 0.5, -step):
                frac = bfrac + df
                if frac < 0:
                    frac = 0.0
                elif frac > 1:
                    frac = 1.0
                h[i] = tot * frac
                h[i + 1] = tot * (1 - frac)
                c = _C(h)
                if c < bC - 1e-16:
                    bC = c
                    bfrac = frac
            h[i] = tot * bfrac
            h[i + 1] = tot * (1 - bfrac)
            if bC < C - 1e-16:
                C = bC
                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def _smooth_conv(h, kernel):
    n = len(h)
    k = len(kernel)
    pad = k // 2
    hp = np.concatenate([h[:pad][::-1], h, h[-pad:][::-1]]) if pad > 0 else h
    out = np.convolve(hp, kernel, mode='valid')
    out = np.maximum(out, 0.0)
    s = out.sum()
    if s <= 0:
        return h
    return out * (h.sum() / s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.7
    rng = np.random.default_rng(424242)

    def remaining():
        return deadline - time.process_time()

    pool = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            pool.append(np.maximum(s.copy(), 0.0))
    for N in [200, 400]:
        x = (np.arange(N) + 0.5) / N * 2 - 1
        pool.append(np.maximum(1 - x * x, 0.0) + 1e-6)

    scored = [(_C(c), c) for c in pool if c.sum() > 0]
    scored.sort(key=lambda t: t[0])
    best_C, best_h = scored[0]

    if start is not None:
        sym = _mirror(np.maximum(np.asarray(start, float).ravel(), 0.0))
        if sym.sum() > 0:
            cs = _C(sym)
            if cs < best_C:
                best_C, best_h = cs, sym

    if remaining() > 0.5:
        end = time.process_time() + remaining() * 0.05
        rh, rc = _adam(best_h, end, rng, lr0=0.008, tol_rel=3e-4,
                       topk=80, kick_amp=0.002)
        if rc < best_C:
            best_C, best_h = rc, rh

    for N_target in [1600, 2400, 3200, 4000]:
        if remaining() < 0.5:
            break
        hu = _resample(best_h, N_target)
        hu = _mirror(hu)
        if hu.sum() <= 0:
            continue
        end = min(deadline - 0.3, time.process_time() + 0.45)
        rh, rc = _adam(hu, end, rng, lr0=0.01, tol_rel=5e-4, topk=80)
        if rc < best_C - 1e-13:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = time.process_time() + remaining() * 0.08
        rh, rc = _adam(best_h, end, rng, lr0=0.002, tol_rel=2e-4, topk=100,
                       kick_amp=0.0015, stall_max=500)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = min(deadline - 0.1, time.process_time() + remaining() * 0.25)
        rh, rc = _pair_coord(best_h, end, rng, step0=0.002, floor=2e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Smoothing + Adam re-polish loop.
    if remaining() > 0.5:
        n_iter = 0
        while remaining() > 0.35 and n_iter < 12:
            n_iter += 1
            kern_choice = [np.array([0.25, 0.5, 0.25]),
                           np.array([1, 2, 3, 2, 1], dtype=float),
                           np.array([1, 3, 5, 3, 1], dtype=float)]
            kern_choice = [k / k.sum() for k in kern_choice]
            k = kern_choice[n_iter % len(kern_choice)]
            hs = _smooth_conv(best_h, k)
            hs = _mirror(hs)
            end = time.process_time() + min(remaining() * 0.35, 1.0)
            rh, rc = _adam(hs, end, rng, lr0=0.006, tol_rel=3e-4,
                           topk=90, kick_amp=0.002, stall_max=400)
            if rc < best_C - 1e-14:
                best_C, best_h = rc, rh

    if remaining() > 0.25:
        end = min(deadline - 0.08, time.process_time() + remaining() * 0.6)
        rh, rc = _pair_coord(best_h, end, rng, step0=0.001, floor=1e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.15:
        end = deadline - 0.03
        rh, rc = _adam(best_h, end, rng, lr0=0.0008, tol_rel=1.5e-4,
                       topk=120, kick_amp=0.0008, stall_max=600)
        if rc < best_C:
            best_C, best_h = rc, rh

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    if best_h.size > 30000:
        best_h = best_h[:30000]
    return best_h

import numpy as np
import time
from scipy.signal import fftconvolve


def _conv(h):
    return fftconvolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _resample(h, N):
    n = len(h)
    if n == N:
        return h.copy()
    cum = np.concatenate([[0.0], np.cumsum(h)])
    edges = np.linspace(0, n, N + 1)
    i = np.clip(np.floor(edges).astype(int), 0, n - 1)
    integ = cum[i] + h[i] * (edges - i)
    out = (integ[1:] - integ[:-1]) / (edges[1:] - edges[:-1])
    return np.maximum(out, 0.0)


def _near_set(conv, mx, tol_rel, topk):
    tol = mx * tol_rel
    near = np.where(conv > mx - tol)[0]
    if len(near) == 0:
        return np.array([int(np.argmax(conv))])
    if len(near) > topk:
        near = near[np.argsort(-conv[near])[:topk]]
    return near


def _adam(h0, end_time, rng, lr0=0.01, tol_rel=1e-3, topk=60,
          kick_amp=0.003, stall_max=300):
    h = np.maximum(np.asarray(h0, dtype=float).copy(), 1e-12)
    N = len(h)
    h *= N / h.sum()
    best_h = h.copy()
    best_C = _C(h)
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-12
    lr = lr0
    t = 0
    stall = 0
    while time.process_time() < end_time:
        t += 1
        s = h.sum()
        conv = _conv(h)
        mx = float(conv.max())
        C = 2.0 * N * mx / (s * s)
        near = _near_set(conv, mx, tol_rel, topk)
        g = np.zeros(N)
        msum = 0.0
        for k in near:
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            idx = np.arange(lo, hi + 1)
            g[idx] += 2.0 * h[k - idx]
            msum += conv[k]
        nl = len(near)
        g /= nl
        mavg = msum / nl
        dC = (2.0 * N / (s * s)) * g - (4.0 * N * mavg / (s * s * s))
        gm = dC * np.maximum(h, 1e-9)
        gn = np.linalg.norm(gm)
        if gn < 1e-18:
            break
        gm /= gn
        m = b1 * m + (1 - b1) * gm
        v = b2 * v + (1 - b2) * gm * gm
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        h_new = h - lr * mhat / (np.sqrt(vhat) + eps) * np.maximum(h, 1e-9)
        h_new = np.maximum(h_new, 0.0)
        s2 = h_new.sum()
        if s2 <= 0:
            h_new = best_h.copy()
            lr *= 0.5
            continue
        h_new *= N / s2
        h = h_new
        if C < best_C - 1e-16:
            best_C = C
            best_h = h.copy()
            stall = 0
        else:
            stall += 1
        if stall > stall_max:
            kick = best_h * (1 + kick_amp * rng.standard_normal(N))
            kick = np.maximum(kick, 0.0)
            if kick.sum() > 0:
                h = kick * (N / kick.sum())
            else:
                h = best_h.copy()
            lr *= 0.85
            m[:] = 0
            v[:] = 0
            t = 1
            stall = 0
    c = _C(h)
    if c < best_C:
        best_h = h.copy()
        best_C = c
    return best_h, best_C


def _pair_coord(h, end_time, rng, step0=0.01, floor=2e-4):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0

    def mks(step):
        return [(1 - step, 1 + step), (1 + step, 1 - step),
                (1 - step * 0.5, 1 + step * 0.5), (1 + step * 0.5, 1 - step * 0.5),
                (1 - step * 0.25, 1 + step * 0.25), (1 + step * 0.25, 1 - step * 0.25)]

    mults = mks(step)
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n - 1)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            o1, o2 = h[i], h[i + 1]
            bC = C
            bm1, bm2 = 1.0, 1.0
            for m1, m2 in mults:
                h[i] = o1 * m1
                h[i + 1] = o2 * m2
                c = _C(h)
                if c < bC - 1e-17:
                    bC = c
                    bm1, bm2 = m1, m2
            h[i] = o1 * bm1
            h[i + 1] = o2 * bm2
            if bm1 != 1.0 or bm2 != 1.0:
                C = bC
                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
            mults = mks(step)
    return h, C


def _triple_coord(h, end_time, rng, step0=0.004, floor=1e-4):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n - 2)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            a, b, c0 = h[i], h[i + 1], h[i + 2]
            tot = a + b + c0
            if tot <= 0:
                continue
            bC = C
            bd = 0.0
            for d in (step, step * 0.5, step * 0.25,
                      -step * 0.25, -step * 0.5, -step):
                nb = b + d * tot
                rem = tot - nb
                if rem < 0 or nb < 0:
                    continue
                sa = a + c0
                if sa <= 0:
                    continue
                h[i] = rem * (a / sa)
                h[i + 1] = nb
                h[i + 2] = rem * (c0 / sa)
                cv = _C(h)
                if cv < bC - 1e-17:
                    bC = cv
                    bd = d
            if bd != 0.0:
                nb = b + bd * tot
                rem = tot - nb
                sa = a + c0
                h[i] = rem * (a / sa)
                h[i + 1] = nb
                h[i + 2] = rem * (c0 / sa)
                C = bC
                improved = True
            else:
                h[i] = a
                h[i + 1] = b
                h[i + 2] = c0
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def _block_smooth(h, end_time, rng, block=8, step0=0.003, floor=5e-5):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0
    while time.process_time() < end_time:
        improved = False
        starts = np.arange(0, n - block + 1)
        rng.shuffle(starts)
        for s0 in starts:
            if time.process_time() >= end_time:
                return h, C
            seg = h[s0:s0 + block]
            tot = seg.sum()
            if tot <= 0:
                continue
            bC = C
            bd = 0.0
            k = np.arange(block)
            bump = np.cos(np.pi * (k + 0.5) / block - np.pi / 2)
            bump -= bump.mean()
            for d in (step, step * 0.5, -step * 0.5, -step):
                cand = seg + d * tot * bump
                if cand.min() < 0:
                    continue
                h[s0:s0 + block] = cand
                cv = _C(h)
                if cv < bC - 1e-17:
                    bC = cv
                    bd = d
            if bd != 0.0:
                h[s0:s0 + block] = seg + bd * tot * bump
                C = bC
                improved = True
            else:
                h[s0:s0 + block] = seg
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    rng = np.random.default_rng(20240113)

    def remaining():
        return deadline - time.process_time()

    pool = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            pool.append(np.maximum(s.copy(), 0.0))
    for N in [200, 400]:
        x = (np.arange(N) + 0.5) / N * 2 - 1
        pool.append(np.maximum(1 - x * x, 0.0) + 1e-6)

    scored = [(_C(c), c) for c in pool if c.sum() > 0]
    scored.sort(key=lambda t: t[0])
    best_C, best_h = scored[0]

    # Phase 1: quick Adam on start.
    if remaining() > 0.5:
        end = time.process_time() + remaining() * 0.05
        rh, rc = _adam(best_h, end, rng, lr0=0.008, tol_rel=3e-4)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Phase 2: upsample ladder.
    for N_target in [1600, 2400, 3200, 4000]:
        if remaining() < 0.4:
            break
        hu = _resample(best_h, N_target)
        if hu.sum() <= 0:
            continue
        end = min(deadline - 0.3, time.process_time() + 0.4)
        rh, rc = _adam(hu, end, rng, lr0=0.01, tol_rel=5e-4)
        if rc < best_C - 1e-13:
            best_C, best_h = rc, rh

    # Phase 2b: fine upsample.
    for N_target in [5000, 6000]:
        if remaining() < 1.5:
            break
        hu = _resample(best_h, N_target)
        if hu.sum() <= 0:
            continue
        end = min(deadline - 0.8, time.process_time() + 0.5)
        rh, rc = _adam(hu, end, rng, lr0=0.008, tol_rel=3e-4)
        if rc < best_C - 1e-13:
            best_C, best_h = rc, rh

    # Phase 3: tight Adam polish.
    if remaining() > 0.3:
        end = time.process_time() + remaining() * 0.07
        rh, rc = _adam(best_h, end, rng, lr0=0.002, tol_rel=2e-4, topk=80,
                       kick_amp=0.0015, stall_max=400)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Phase 4: triple-coordinate polish.
    if remaining() > 0.3:
        end = min(deadline - 0.4, time.process_time() + remaining() * 0.16)
        rh, rc = _triple_coord(best_h, end, rng, step0=0.004, floor=1e-4)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Phase 5: block-smoothing polish.
    if remaining() > 0.3:
        end = min(deadline - 0.3, time.process_time() + remaining() * 0.18)
        rh, rc = _block_smooth(best_h, end, rng, block=8, step0=0.003,
                               floor=5e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Phase 5b: NEW - finer block-smooth with larger block.
    if remaining() > 0.3:
        end = min(deadline - 0.25, time.process_time() + remaining() * 0.20)
        rh, rc = _block_smooth(best_h, end, rng, block=16, step0=0.002,
                               floor=2e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Phase 6: pairwise coordinate polish.
    if remaining() > 0.3:
        end = min(deadline - 0.15, time.process_time() + remaining() * 0.20)
        rh, rc = _pair_coord(best_h, end, rng, step0=0.004, floor=1e-4)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Phase 6b: another block-smooth at finer step.
    if remaining() > 0.3:
        end = min(deadline - 0.15, time.process_time() + remaining() * 0.15)
        rh, rc = _block_smooth(best_h, end, rng, block=12, step0=0.0015,
                               floor=2e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    # Phase 7: final micro Adam polish.
    if remaining() > 0.15:
        end = deadline - 0.03
        rh, rc = _adam(best_h, end, rng, lr0=0.0005, tol_rel=1.5e-4,
                       topk=120, kick_amp=0.0006, stall_max=800)
        if rc < best_C:
            best_C, best_h = rc, rh

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    if best_h.size > 30000:
        best_h = best_h[:30000]
    return best_h

