                continue
            bC = C
            bd = 0.0
            k = np.arange(block)
            bump = np.cos(np.pi * (k + 0.5) / block - np.pi / 2)
            bump -= bump.mean()
            for d in (step, step * 0.5, -step * 0.5, -step):
                cand = seg + d * tot * bump
                if cand.min() < 0:
