def _window_coord(h, end_time, rng, win=5, step0=0.002, floor=4e-5):
    """Contiguous-window shift: move mass along a smooth ramp within a window.
    Targets the flat plateau of tied maxima directly."""
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0
    k = np.arange(win)
    ramp = (k - (win - 1) / 2.0)
    ramp -= ramp.mean()
    rn = np.linalg.norm(ramp)
    if rn > 0:
        ramp /= rn
    while time.process_time() < end_time:
        improved = False
        starts = np.arange(0, n - win + 1)
        rng.shuffle(starts)
        for s0 in starts:
            if time.process_time() >= end_time:
                return h, C
            seg = h[s0:s0 + win]
            tot = seg.sum()
            if tot <= 0:
                continue
            bC = C
            bd = 0.0
            for d in (step, step * 0.5, -step * 0.5, -step):
                cand = seg + d * tot * ramp
                if cand.min() < 0:
                    continue
                h[s0:s0 + win] = cand
                cv = _C(h)
                if cv < bC - 1e-17:
                    bC = cv
                    bd = d
            if bd != 0.0:
                h[s0:s0 + win] = seg + bd * tot * ramp
                C = bC
                improved = True
            else:
                h[s0:s0 + win] = seg
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


