        s = h.sum()
        conv = _conv(h)
        mx = float(conv.max())
        C = 2.0 * N * mx / (s * s)
        near = _near_set(conv, mx, tol_rel, topk)
        g = np.zeros(N)
        msum = 0.0
        for k in near:
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            idx = np.arange(lo, hi + 1)
            g[idx] += 2.0 * h[k - idx]
            msum += conv[k]
        nl = len(near)
        g /= nl
        mavg = msum / nl
        dC = (2.0 * N / (s * s)) * g - (4.0 * N * mavg / (s * s * s))
        gm = dC * np.maximum(h, 1e-9)
        gn = np.linalg.norm(gm)
        if gn < 1e-18:
            break
        gm /= gn
        m = b1 * m + (1 - b1) * gm
        v = b2 * v + (1 - b2) * gm * gm
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        h_new = h - lr * mhat / (np.sqrt(vhat) + eps) * np.maximum(h, 1e-9)
        h_new = np.maximum(h_new, 0.0)
        s2 = h_new.sum()
        if s2 <= 0:
            h_new = best_h.copy()
            lr *= 0.5
            continue
        h_new *= N / s2
        h = h_new
        if C < best_C - 1e-16:
            best_C = C
            best_h = h.copy()
            stall = 0
        else:
            stall += 1
        if stall > stall_max:
            kick = best_h * (1 + kick_amp * rng.standard_normal(N))
            kick = np.maximum(kick, 0.0)
            if kick.sum() > 0:
                h = kick * (N / kick.sum())
            else:
                h = best_h.copy()
            lr *= 0.85
            m[:] = 0
            v[:] = 0
            t = 1
            stall = 0
    c = _C(h)
    if c < best_C:
        best_h = h.copy()
        best_C = c
    return best_h, best_C


def _pair_coord(h, end_time, rng, step0=0.01, floor=2e-4):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0

    def mks(step):
        return [(1 - step, 1 + step), (1 + step, 1 - step),
                (1 - step * 0.5, 1 + step * 0.5), (1 + step * 0.5, 1 - step * 0.5),
                (1 - step * 0.25, 1 + step * 0.25), (1 + step * 0.25, 1 - step * 0.25)]

    mults = mks(step)
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n - 1)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            o1, o2 = h[i], h[i + 1]
            bC = C
            bm1, bm2 = 1.0, 1.0
            for m1, m2 in mults:
                h[i] = o1 * m1
                h[i + 1] = o2 * m2
                c = _C(h)
                if c < bC - 1e-17:
                    bC = c
                    bm1, bm2 = m1, m2
            h[i] = o1 * bm1
            h[i + 1] = o2 * bm2
            if bm1 != 1.0 or bm2 != 1.0:
                C = bC
                improved = True
        if not improved:
            if step < floor:
                break
            step *= 0.5
            mults = mks(step)
    return h, C


def _triple_coord(h, end_time, rng, step0=0.004, floor=1e-4):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0
    while time.process_time() < end_time:
        improved = False
        idxs = np.arange(n - 2)
        rng.shuffle(idxs)
        for i in idxs:
            if time.process_time() >= end_time:
                return h, C
            a, b, c0 = h[i], h[i + 1], h[i + 2]
            tot = a + b + c0
            if tot <= 0:
                continue
            bC = C
            bd = 0.0
            for d in (step, step * 0.5, step * 0.25,
                      -step * 0.25, -step * 0.5, -step):
                nb = b + d * tot
                rem = tot - nb
                if rem < 0 or nb < 0:
                    continue
                sa = a + c0
                if sa <= 0:
                    continue
                h[i] = rem * (a / sa)
                h[i + 1] = nb
                h[i + 2] = rem * (c0 / sa)
                cv = _C(h)
                if cv < bC - 1e-17:
                    bC = cv
                    bd = d
            if bd != 0.0:
                nb = b + bd * tot
                rem = tot - nb
                sa = a + c0
                h[i] = rem * (a / sa)
                h[i + 1] = nb
                h[i + 2] = rem * (c0 / sa)
                C = bC
                improved = True
            else:
                h[i] = a
                h[i + 1] = b
                h[i + 2] = c0
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def _block_smooth(h, end_time, rng, block=8, step0=0.003, floor=5e-5):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0
    while time.process_time() < end_time:
        improved = False
        starts = np.arange(0, n - block + 1)
        rng.shuffle(starts)
        for s0 in starts:
            if time.process_time() >= end_time:
                return h, C
            seg = h[s0:s0 + block]
            tot = seg.sum()
            if tot <= 0:
                continue
            bC = C
            bd = 0.0
            k = np.arange(block)
            bump = np.cos(np.pi * (k + 0.5) / block - np.pi / 2)
            bump -= bump.mean()
            for d in (step, step * 0.5, -step * 0.5, -step):
                cand = seg + d * tot * bump
                if cand.min() < 0:
                    continue
                h[s0:s0 + block] = cand
                cv = _C(h)
                if cv < bC - 1e-17:
                    bC = cv
                    bd = d
            if bd != 0.0:
                h[s0:s0 + block] = seg + bd * tot * bump
                C = bC
                improved = True
            else:
                h[s0:s0 + block] = seg
        if not improved:
            if step < floor:
                break
            step *= 0.5
    return h, C


def _window_coord(h, end_time, rng, win=5, step0=0.002, floor=4e-5):
    h = np.maximum(h.copy(), 0.0)
    C = _C(h)
    n = len(h)
    step = step0
    k = np.arange(win)
    ramp = (k - (win - 1) / 2.0)
    ramp -= ramp.mean()
    rn = np.linalg.norm(ramp)
    if rn > 0:
