            bC = C
            bd = 0.0
            for d in (step, step * 0.5, -step * 0.5, -step):
                cand = seg + d * tot * ramp
                if cand.min() < 0:
                    continue
                h[s0:s0 + win] = cand
                cv = _C(h)
                if cv < bC - 1e-17:
