def _spline_polish(h, end_time, rng, knots=24, trials=40):
    """Global smooth reparametrization: represent h as a positive B-spline-ish
    comb of cosine bumps, optimize the coordinates. This escapes local minima
    that fine-grained coordinate edits (pair/triple/block) cannot."""
    n = len(h)
    xs = (np.arange(n) + 0.5) / n

    def build(weights):
        out = np.zeros(n)
        cen = (np.arange(knots) + 0.5) / knots
        for j in range(knots):
            d = np.abs(xs - cen[j])
            d = np.minimum(d, 1.0 - d)
            w = np.maximum(0.0, 1.0 - d * knots / 1.6)
            out += weights[j] * w * w
        return out

    w0 = np.ones(knots)
    # initialize weights by projecting h
    cen = (np.arange(knots) + 0.5) / knots
    for j in range(knots):
        d = np.abs(xs - cen[j])
        d = np.minimum(d, 1.0 - d)
        wmask = np.maximum(0.0, 1.0 - d * knots / 1.6) ** 2
        denom = (wmask * wmask).sum()
        if denom > 0:
            w0[j] = max(1e-4, (h * wmask).sum() / denom)

    best_w = w0.copy()
    best_h = build(best_w)
    if best_h.sum() <= 0:
        return h, _C(h)
    best_h *= n / best_h.sum()
    best_C = _C(best_h)

    step = 0.05
    while time.process_time() < end_time:
        improved = False
        order = np.arange(knots)
        rng.shuffle(order)
        for j in order:
            if time.process_time() >= end_time:
                break
            for d in (step, step * 0.5, -step * 0.5, -step):
                cand = best_w.copy()
                cand[j] = max(0.0, cand[j] * (1.0 + d))
                ch = build(cand)
                if ch.sum() <= 0:
                    continue
                ch *= n / ch.sum()
                c = _C(ch)
                if c < best_C - 1e-17:
                    best_C = c
                    best_w = cand
                    best_h = ch
                    improved = True
                    break
        if not improved:
            if step < 1e-4:
                break
            step *= 0.5
    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    rng = np.random.default_rng(20240113)

    def remaining():
        return deadline - time.process_time()

    pool = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            pool.append(np.maximum(s.copy(), 0.0))
    for N in [200, 400]:
        x = (np.arange(N) + 0.5) / N * 2 - 1
        pool.append(np.maximum(1 - x * x, 0.0) + 1e-6)

    scored = [(_C(c), c) for c in pool if c.sum() > 0]
    scored.sort(key=lambda t: t[0])
    best_C, best_h = scored[0]

    if remaining() > 0.5:
        end = time.process_time() + remaining() * 0.04
        rh, rc = _adam(best_h, end, rng, lr0=0.008, tol_rel=3e-4)
        if rc < best_C:
            best_C, best_h = rc, rh

    for N_target in [1600, 2400, 3200, 4000]:
        if remaining() < 0.4:
            break
        hu = _resample(best_h, N_target)
        if hu.sum() <= 0:
            continue
        end = min(deadline - 0.3, time.process_time() + 0.35)
        rh, rc = _adam(hu, end, rng, lr0=0.01, tol_rel=5e-4)
        if rc < best_C - 1e-13:
            best_C, best_h = rc, rh

    for N_target in [5000, 6000]:
        if remaining() < 1.5:
            break
        hu = _resample(best_h, N_target)
        if hu.sum() <= 0:
            continue
        end = min(deadline - 0.8, time.process_time() + 0.45)
        rh, rc = _adam(hu, end, rng, lr0=0.008, tol_rel=3e-4)
        if rc < best_C - 1e-13:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = time.process_time() + remaining() * 0.06
        rh, rc = _adam(best_h, end, rng, lr0=0.002, tol_rel=2e-4, topk=80,
                       kick_amp=0.0015, stall_max=400)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = min(deadline - 0.4, time.process_time() + remaining() * 0.12)
        rh, rc = _triple_coord(best_h, end, rng, step0=0.004, floor=1e-4)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = min(deadline - 0.3, time.process_time() + remaining() * 0.14)
        rh, rc = _block_smooth(best_h, end, rng, block=8, step0=0.003,
                               floor=5e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = min(deadline - 0.2, time.process_time() + remaining() * 0.14)
        rh, rc = _window_coord(best_h, end, rng, win=5, step0=0.002,
                               floor=4e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = min(deadline - 0.15, time.process_time() + remaining() * 0.14)
        rh, rc = _pair_coord(best_h, end, rng, step0=0.004, floor=1e-4)
        if rc < best_C:
            best_C, best_h = rc, rh

    # NEW: global smooth reparametrization to escape fine-grained local minima.
    if remaining() > 0.4:
        end = min(deadline - 0.25, time.process_time() + remaining() * 0.30)
        rh, rc = _spline_polish(best_h, end, rng, knots=24)
        if rc < best_C - 1e-13:
            # re-expand to a finer grid via resampling to keep resolution
            if best_h.size < 4000:
                rh2 = _resample(rh, 4000)
                rc2 = _C(rh2)
                if rc2 < rc:
                    rh, rc = rh2, rc2
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = min(deadline - 0.15, time.process_time() + remaining() * 0.12)
        rh, rc = _block_smooth(best_h, end, rng, block=12, step0=0.0015,
                               floor=2e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.3:
        end = min(deadline - 0.12, time.process_time() + remaining() * 0.12)
        rh, rc = _window_coord(best_h, end, rng, win=9, step0=0.001,
                               floor=2e-5)
        if rc < best_C:
            best_C, best_h = rc, rh

    if remaining() > 0.15:
        end = deadline - 0.03
        rh, rc = _adam(best_h, end, rng, lr0=0.0005, tol_rel=1.5e-4,
                       topk=120, kick_amp=0.0006, stall_max=800)
        if rc < best_C:
            best_C, best_h = rc, rh

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    if best_h.size > 30000:
        best_h = best_h[:30000]
    return best_h
